  (
    {
      radius = 350,
      color = '#6366f1',
      borderColor = '#818cf8',
      opacity = 0.85,
      spread = 60,
      mode = 'both',
      smoothing = 0.2,
      disabled = false,
      className,
      style,
      children,
      ...props
