import React, { useRef } from 'react';
import {
  View,
  PanResponder,
  Animated,
  StyleSheet,
  type ViewProps,
} from 'react-native';

export interface SpotlightCardProps extends ViewProps {
  radius?: number;
  color?: string;
  borderColor?: string;
  opacity?: number;
  children?: React.ReactNode;
}

export function SpotlightCard({
  radius = 350,
  color = '#6366f1',
  borderColor = '#818cf8',
  opacity = 0.85,
  style,
  children,
  ...props
}: SpotlightCardProps) {
  const pan = useRef(new Animated.ValueXY({ x: 0, y: 0 })).current;
  const glowOpacity = useRef(new Animated.Value(0)).current;

  const panResponder = useRef(
    PanResponder.create({
      onStartShouldSetPanResponder: () => true,
      onMoveShouldSetPanResponder: () => true,
      onPanResponderGrant: (evt) => {
        pan.setValue({ x: evt.nativeEvent.locationX, y: evt.nativeEvent.locationY });
        Animated.timing(glowOpacity, {
          toValue: opacity,
          duration: 150,
          useNativeDriver: false,
        }).start();
      },
      onPanResponderMove: (evt) => {
        pan.setValue({ x: evt.nativeEvent.locationX, y: evt.nativeEvent.locationY });
      },
      onPanResponderRelease: () => {
        Animated.timing(glowOpacity, {
          toValue: 0,
          duration: 250,
          useNativeDriver: false,
        }).start();
      },
    })
  ).current;

  return (
    <View
      style={[styles.card, style]}
      {...panResponder.panHandlers}
      {...props}
    >
      <Animated.View
        pointerEvents="none"
        style={[
          styles.glow,
          {
            width: radius * 2,
            height: radius * 2,
            borderRadius: radius,
            backgroundColor: color,
            opacity: glowOpacity,
            transform: [
              { translateX: Animated.subtract(pan.x, new Animated.Value(radius)) },
              { translateY: Animated.subtract(pan.y, new Animated.Value(radius)) },
            ],
          },
        ]}
      />
      <View style={styles.content}>{children}</View>
    </View>
  );
}

const styles = StyleSheet.create({
  card: {
    borderRadius: 16,
    borderWidth: 1,
    borderColor: 'rgba(255, 255, 255, 0.1)',
    backgroundColor: 'rgba(24, 24, 27, 0.6)',
    overflow: 'hidden',
    position: 'relative',
    padding: 24,
  },
  glow: {
    position: 'absolute',
  },
  content: {
    zIndex: 1,
  },
});

